/** Generated by scaffold-crud-pages. Query hooks for Users.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchUsersList,
  fetchUsersById,
  createUsers,
  updateUsers,
  deleteUsers,
  type FetchUsersListParams,
} from '~/services/httpServices/usersService';
import type { CreateUsersRequest, UpdateUsersRequest } from '~/types/users';

const DOMAIN = 'users';

export function useUsersList(params?: FetchUsersListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchUsersList(params),
  });
}

export function useUsers(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchUsersById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateUsers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateUsersRequest) => createUsers(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateUsers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateUsersRequest }) =>
      updateUsers(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteUsers() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteUsers(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
